/// <summary>
/// MET_5012_RebateProcess Load Number sequence for Custom Rebate Transaction number
/// </summary>
[ExtensionOf(classStr(NumberSeqModuleSalesOrder))]
final class METNumberSeqModuleSalesOrder_Extension
{
}

Method.Source:
    /// <summary>
    /// Configures all the data types that are being used by the module.
    /// </summary>
    protected void loadModule()
    {
        next loadModule();

        NumberSeqDatatype datatype = NumberSeqDatatype::construct();

        datatype.parmDatatypeId(extendedTypeNum(METRebateTransId));
        datatype.parmReferenceHelp("@MET:METRebateTransId");
        datatype.parmWizardIsContinuous(false);
        datatype.parmWizardIsManual(NoYes::No);
        datatype.parmWizardIsChangeDownAllowed(NoYes::No);
        datatype.parmWizardIsChangeUpAllowed(NoYes::No);

        this.create(datatype);

    }
